const TREATMENT_CSS = ":host {\n  --wa-blue: #1688f8;\n  --wa-blue-soft: color-mix(in srgb, var(--wa-blue) 13%, transparent);\n  --wa-cyan: #0ab6c6;\n  --wa-irrigation: #3aad72;\n  --wa-ok: var(--success-color, #2eaf6f);\n  --wa-warn: var(--warning-color, #e99417);\n  --wa-bad: var(--error-color, #df4747);\n  --wa-muted: var(--secondary-text-color, #707783);\n  --wa-divider: var(--divider-color, rgba(112, 119, 131, 0.22));\n  --wa-card: var(--ha-card-background, var(--card-background-color, #fff));\n  --wa-surface: var(--secondary-background-color, #f2f5f8);\n  --wa-bg: var(--primary-background-color, #f7f9fb);\n  --wa-text: var(--primary-text-color, #20242a);\n  display: block;\n  width: 100%;\n  height: 100%;\n  min-height: 100%;\n  color: var(--wa-text);\n  font-family: var(--paper-font-body1_-_font-family, Roboto, system-ui, -apple-system, sans-serif);\n  -webkit-tap-highlight-color: transparent;\n}\n\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nbutton {\n  color: inherit;\n  font: inherit;\n}\n\nbutton:focus-visible {\n  outline: 3px solid color-mix(in srgb, var(--wa-blue) 46%, transparent);\n  outline-offset: 2px;\n}\n\nbutton:active {\n  filter: brightness(0.96);\n}\n\n[hidden] {\n  display: none !important;\n}\n\n.app-shell {\n  isolation: isolate;\n  background:\n    radial-gradient(circle at 8% 2%, color-mix(in srgb, var(--wa-blue) 10%, transparent), transparent 31rem),\n    radial-gradient(circle at 92% 22%, color-mix(in srgb, var(--wa-cyan) 8%, transparent), transparent 28rem),\n    var(--wa-bg);\n}\n\n.app-header {\n  box-shadow: 0 7px 24px rgba(19, 43, 69, 0.06);\n}\n\n.header-action,\n.header-title,\n.tabbar button,\n.period-selector button,\n.pressure-card,\n.reading-tile,\n.meter-property,\n.diagnostic-entity {\n  border: 0;\n  cursor: pointer;\n}\n\n.header-action {\n  justify-self: center;\n}\n\n.header-action ha-icon {\n  --mdc-icon-size: 25px;\n}\n\n.header-action.busy ha-icon {\n  animation: wa-spin 0.8s linear infinite;\n}\n\n.header-title {\n  color: inherit;\n}\n\n.header-title:active {\n  border-color: color-mix(in srgb, var(--wa-blue) 42%, var(--wa-divider));\n  background: color-mix(in srgb, var(--wa-blue) 13%, var(--wa-card));\n  box-shadow: 0 2px 7px rgba(23, 45, 76, 0.05);\n}\n\n.header-title strong {\n  overflow: hidden;\n  font-size: clamp(16px, 4.6vw, 23px);\n  font-weight: 800;\n  line-height: 1.05;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.header-title small {\n  color: var(--wa-muted);\n  font-size: clamp(11px, 3.2vw, 14px);\n  font-weight: 560;\n  letter-spacing: 0.01em;\n  line-height: 1.2;\n}\n\n.canvas-viewport.zoomed {\n  overflow: hidden;\n  touch-action: none;\n}\n\n.work-canvas {\n  transform: translate3d(0, 0, 0) scale(1);\n  will-change: transform;\n}\n\n.work-content {\n  display: block;\n}\n\n.page {\n  display: grid;\n  width: min(100%, 1080px);\n  min-width: 0;\n  margin: 0 auto;\n  gap: 14px;\n}\n\n.page > *,\n.stats-summary-grid,\n.chart-card,\n.chart-heading,\n.chart-host {\n  min-width: 0;\n}\n\n.card,\n.section-block,\n.period-selector,\n.stat-total,\n.diagnostic-group {\n  border: 1px solid color-mix(in srgb, var(--wa-divider) 74%, transparent);\n  border-radius: 22px;\n  background: color-mix(in srgb, var(--wa-card) 96%, transparent);\n  box-shadow: 0 12px 34px rgba(19, 43, 69, 0.07);\n}\n\n.card,\n.section-block,\n.diagnostic-group {\n  padding: 17px;\n}\n\n.eyebrow {\n  margin: 0 0 4px;\n  color: var(--wa-blue);\n  font-size: 12px;\n  font-weight: 800;\n  letter-spacing: 0.1em;\n  line-height: 1.2;\n  text-transform: uppercase;\n}\n\nh1,\nh2,\np {\n  margin-top: 0;\n}\n\nh1 {\n  margin-bottom: 4px;\n  font-size: clamp(21px, 5.4vw, 28px);\n  font-weight: 800;\n  line-height: 1.13;\n  letter-spacing: -0.025em;\n}\n\nh2 {\n  margin-bottom: 0;\n  font-size: 18px;\n  font-weight: 780;\n  line-height: 1.2;\n}\n\n.system-hero {\n  position: relative;\n  overflow: hidden;\n}\n\n.system-hero::before {\n  position: absolute;\n  inset: 0 0 auto;\n  height: 4px;\n  background: var(--wa-muted);\n  content: \"\";\n}\n\n.system-hero.ok::before {\n  background: var(--wa-ok);\n}\n\n.system-hero.warn::before {\n  background: var(--wa-warn);\n}\n\n.system-hero.bad::before {\n  background: var(--wa-bad);\n}\n\n.hero-heading,\n.section-heading,\n.chart-heading,\n.meter-card-head {\n  display: flex;\n  align-items: center;\n}\n\n.hero-heading {\n  gap: 12px;\n  margin-bottom: 15px;\n}\n\n.hero-heading > div:last-child,\n.meter-card-head > div:nth-child(2) {\n  min-width: 0;\n}\n\n.hero-heading p:last-child,\n.page-heading p:last-child,\n.consumption-head p:last-child {\n  margin: 0;\n  color: var(--wa-muted);\n  font-size: 13px;\n  line-height: 1.35;\n}\n\n.hero-icon,\n.meter-card-icon {\n  display: grid;\n  flex: 0 0 auto;\n  place-items: center;\n  color: white;\n  background: linear-gradient(145deg, var(--wa-blue), var(--wa-cyan));\n  box-shadow: 0 9px 22px color-mix(in srgb, var(--wa-blue) 26%, transparent);\n}\n\n.hero-icon {\n  width: 49px;\n  height: 49px;\n  border-radius: 18px;\n}\n\n.hero-icon ha-icon {\n  --mdc-icon-size: 29px;\n}\n\n.pressure-grid,\n.meter-reading-grid,\n.snapshot-grid,\n.stats-summary-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 10px;\n}\n\n.pressure-card {\n  display: grid;\n  min-width: 0;\n  min-height: 148px;\n  align-content: start;\n  gap: 5px;\n  padding: 14px;\n  border: 1px solid color-mix(in srgb, var(--wa-muted) 24%, transparent);\n  border-radius: 18px;\n  background: color-mix(in srgb, var(--wa-surface) 70%, var(--wa-card));\n  text-align: left;\n}\n\n.pressure-card.ok {\n  border-color: color-mix(in srgb, var(--wa-ok) 42%, transparent);\n  background: color-mix(in srgb, var(--wa-ok) 11%, var(--wa-card));\n}\n\n.pressure-card.warn {\n  border-color: color-mix(in srgb, var(--wa-warn) 46%, transparent);\n  background: color-mix(in srgb, var(--wa-warn) 12%, var(--wa-card));\n}\n\n.pressure-card.bad {\n  border-color: color-mix(in srgb, var(--wa-bad) 46%, transparent);\n  background: color-mix(in srgb, var(--wa-bad) 12%, var(--wa-card));\n}\n\n.pressure-label {\n  display: flex;\n  min-width: 0;\n  align-items: center;\n  gap: 6px;\n  color: var(--wa-muted);\n  font-size: 12px;\n  font-weight: 720;\n  line-height: 1.25;\n}\n\n.pressure-label ha-icon {\n  --mdc-icon-size: 18px;\n  flex: 0 0 auto;\n  color: var(--wa-blue);\n}\n\n.pressure-card > strong {\n  margin-top: 6px;\n  font-size: clamp(22px, 6.2vw, 30px);\n  font-weight: 850;\n  line-height: 1;\n  letter-spacing: -0.04em;\n  white-space: nowrap;\n}\n\n.pressure-status {\n  font-size: 12px;\n  font-weight: 790;\n  line-height: 1.25;\n}\n\n.pressure-card.ok .pressure-status {\n  color: var(--wa-ok);\n}\n\n.pressure-card.warn .pressure-status {\n  color: var(--wa-warn);\n}\n\n.pressure-card.bad .pressure-status {\n  color: var(--wa-bad);\n}\n\n.pressure-card small {\n  margin-top: auto;\n  padding-top: 4px;\n  color: var(--wa-muted);\n  font-size: 12px;\n  line-height: 1.25;\n}\n\n.pressure-thresholds {\n  display: grid;\n  gap: 8px;\n  margin-top: 11px;\n  padding: 12px;\n  border: 1px solid color-mix(in srgb, var(--wa-divider) 72%, transparent);\n  border-radius: 17px;\n  background: color-mix(in srgb, var(--wa-surface) 66%, transparent);\n}\n\n.page-meters .meter-thresholds {\n  margin-top: 0;\n  padding: 17px;\n  background: color-mix(in srgb, var(--wa-card) 96%, transparent);\n  box-shadow: 0 12px 34px rgba(19, 43, 69, 0.07);\n}\n\n.thresholds-title {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  font-size: 13px;\n}\n\n.thresholds-title ha-icon {\n  --mdc-icon-size: 18px;\n  color: var(--wa-blue);\n}\n\n.threshold-row {\n  display: grid;\n  grid-template-columns: 76px minmax(0, 1fr);\n  align-items: start;\n  gap: 8px;\n}\n\n.threshold-row > span {\n  padding-top: 3px;\n  color: var(--wa-muted);\n  font-size: 12px;\n  font-weight: 760;\n}\n\n.threshold-row p {\n  margin: 0;\n  color: var(--wa-muted);\n  font-size: 12px;\n  line-height: 1.65;\n}\n\n.threshold-row b {\n  display: inline-block;\n  padding: 0 5px;\n  border-radius: 6px;\n  font-size: 12px;\n  font-weight: 850;\n  line-height: 19px;\n  white-space: nowrap;\n}\n\n.threshold-row b.ok {\n  color: color-mix(in srgb, var(--wa-ok) 82%, var(--wa-text));\n  background: color-mix(in srgb, var(--wa-ok) 15%, transparent);\n}\n\n.threshold-row b.warn {\n  color: color-mix(in srgb, var(--wa-warn) 86%, var(--wa-text));\n  background: color-mix(in srgb, var(--wa-warn) 17%, transparent);\n}\n\n.threshold-row b.bad {\n  color: color-mix(in srgb, var(--wa-bad) 85%, var(--wa-text));\n  background: color-mix(in srgb, var(--wa-bad) 15%, transparent);\n}\n\n.section-heading,\n.chart-heading {\n  justify-content: space-between;\n  gap: 10px;\n  margin-bottom: 13px;\n}\n\n.section-heading > ha-icon {\n  --mdc-icon-size: 24px;\n  color: var(--wa-blue);\n}\n\n.reading-tile {\n  display: grid;\n  min-width: 0;\n  gap: 4px;\n  padding: 14px;\n  border-radius: 17px;\n  background: color-mix(in srgb, var(--wa-blue) 9%, var(--wa-card));\n  text-align: left;\n}\n\n.reading-tile.irrigation {\n  background: color-mix(in srgb, var(--wa-irrigation) 10%, var(--wa-card));\n}\n\n.reading-tile span,\n.snapshot-card > span,\n.stat-total span {\n  color: var(--wa-muted);\n  font-size: 12px;\n  font-weight: 720;\n  line-height: 1.25;\n}\n\n.reading-tile strong {\n  overflow: hidden;\n  font-size: clamp(18px, 4.8vw, 25px);\n  font-weight: 820;\n  line-height: 1.15;\n  letter-spacing: -0.025em;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.reading-tile small {\n  color: var(--wa-muted);\n  font-size: 12px;\n}\n\n.snapshot-card {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  gap: 7px 10px;\n  min-width: 0;\n  padding: 14px;\n  border: 1px solid color-mix(in srgb, var(--wa-divider) 70%, transparent);\n  border-radius: 17px;\n  background: color-mix(in srgb, var(--wa-surface) 52%, var(--wa-card));\n}\n\n.snapshot-card > strong {\n  grid-column: 1 / -1;\n  overflow: hidden;\n  font-size: 20px;\n  font-weight: 820;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.snapshot-card > div {\n  display: grid;\n  gap: 2px;\n}\n\n.snapshot-card > div:last-of-type {\n  text-align: right;\n}\n\n.snapshot-card small {\n  color: var(--wa-muted);\n  font-size: 12px;\n}\n\n.snapshot-card b {\n  font-size: 12px;\n}\n\n.snapshot-card[data-state=\"error\"] > strong,\n.snapshot-card[data-state=\"partial\"] > strong,\n.snapshot-card[data-state=\"empty\"] > strong {\n  color: var(--wa-muted);\n  font-size: 13px;\n}\n\n.statistics-coverage {\n  grid-column: 1 / -1;\n  color: var(--wa-muted);\n  font-size: 12px;\n  line-height: 1.5;\n  white-space: normal;\n}\n\n.consumption-head,\n.page-heading {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 14px;\n}\n\n.period-badge,\n.data-badge {\n  flex: 0 0 auto;\n  padding: 7px 10px;\n  border-radius: 999px;\n  color: var(--wa-blue);\n  background: var(--wa-blue-soft);\n  font-size: 12px;\n  font-weight: 800;\n  white-space: nowrap;\n}\n\n.period-selector {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 5px;\n  padding: 5px;\n}\n\n.period-selector button {\n  min-width: 0;\n  min-height: 39px;\n  padding: 6px 4px;\n  border-radius: 15px;\n  color: var(--wa-muted);\n  background: transparent;\n  font-size: 12px;\n  font-weight: 750;\n  white-space: nowrap;\n}\n\n.period-selector button.active {\n  color: white;\n  background: linear-gradient(135deg, var(--wa-blue), var(--wa-cyan));\n  box-shadow: 0 7px 17px color-mix(in srgb, var(--wa-blue) 23%, transparent);\n}\n\n.stats-summary-grid {\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n}\n\n.stat-total {\n  display: grid;\n  min-width: 0;\n  gap: 5px;\n  padding: 14px;\n}\n\n.stat-total strong {\n  overflow: hidden;\n  font-size: clamp(17px, 4.5vw, 24px);\n  font-weight: 820;\n  letter-spacing: -0.025em;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.stat-total.drinking {\n  border-color: color-mix(in srgb, var(--wa-blue) 30%, transparent);\n}\n\n.stat-total.irrigation {\n  border-color: color-mix(in srgb, var(--wa-irrigation) 34%, transparent);\n}\n\n.stat-total.combined {\n  border-color: color-mix(in srgb, var(--wa-cyan) 34%, transparent);\n}\n\n.chart-card {\n  min-height: 322px;\n  overflow: hidden;\n}\n\n.chart-legend {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n  gap: 7px 11px;\n  color: var(--wa-muted);\n  font-size: 12px;\n  font-weight: 700;\n}\n\n.chart-legend span::before {\n  display: inline-block;\n  width: 8px;\n  height: 8px;\n  margin-right: 4px;\n  border-radius: 3px;\n  background: var(--wa-blue);\n  content: \"\";\n}\n\n.chart-legend .irrigation::before {\n  background: var(--wa-irrigation);\n}\n\n.chart-host {\n  display: grid;\n  width: 100%;\n  min-height: 238px;\n  place-items: stretch;\n  overflow-x: hidden;\n  overflow-y: hidden;\n}\n\n.chart-state {\n  display: grid;\n  min-height: 238px;\n  place-items: center;\n  padding: 20px;\n  color: var(--wa-muted);\n  font-size: 13px;\n  text-align: center;\n}\n\n.chart-state.error {\n  color: var(--wa-bad);\n}\n\n.bar-chart {\n  display: grid;\n  grid-template-columns: repeat(var(--bucket-count), minmax(0, 1fr));\n  align-items: end;\n  gap: clamp(1px, 0.7vw, 3px);\n  width: 100%;\n  min-width: 0;\n  height: 238px;\n  padding: 15px 2px 0;\n  border-bottom: 1px solid var(--wa-divider);\n  background: repeating-linear-gradient(\n    to top,\n    transparent 0,\n    transparent 54px,\n    color-mix(in srgb, var(--wa-divider) 55%, transparent) 55px,\n    transparent 56px\n  );\n}\n\n.bar-bucket {\n  display: grid;\n  grid-template-rows: minmax(0, 1fr) 22px;\n  align-self: stretch;\n  gap: 4px;\n  min-width: 0;\n}\n\n.bars {\n  display: flex;\n  align-items: end;\n  justify-content: center;\n  gap: 2px;\n  min-height: 0;\n}\n\n.bars i {\n  display: block;\n  width: min(42%, 14px);\n  min-height: 0;\n  border-radius: 5px 5px 2px 2px;\n  background: linear-gradient(to top, #0777e7, var(--wa-blue));\n}\n\n.bars i.irrigation {\n  background: linear-gradient(to top, #218f58, var(--wa-irrigation));\n}\n\n.bar-bucket > span {\n  overflow: hidden;\n  color: var(--wa-muted);\n  font-size: 12px;\n  line-height: 18px;\n  text-align: center;\n  text-overflow: clip;\n  white-space: nowrap;\n}\n\n.meters-list {\n  display: grid;\n  gap: 14px;\n}\n\n.meter-card {\n  position: relative;\n  overflow: hidden;\n}\n\n.meter-card::before {\n  position: absolute;\n  inset: 0 auto 0 0;\n  width: 4px;\n  background: var(--wa-blue);\n  content: \"\";\n}\n\n.meter-card.irrigation::before {\n  background: var(--wa-irrigation);\n}\n\n.meter-card-head {\n  gap: 11px;\n  margin-bottom: 15px;\n}\n\n.meter-card-icon {\n  width: 43px;\n  height: 43px;\n  border-radius: 16px;\n}\n\n.meter-card.irrigation .meter-card-icon {\n  background: linear-gradient(145deg, var(--wa-irrigation), var(--wa-cyan));\n}\n\n.meter-card-head p {\n  margin: 0 0 2px;\n  color: var(--wa-muted);\n  font-size: 12px;\n  font-weight: 720;\n}\n\n.meter-card-head strong {\n  display: block;\n  overflow: hidden;\n  font-size: clamp(21px, 5.5vw, 29px);\n  font-weight: 830;\n  line-height: 1.1;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.data-badge {\n  margin-left: auto;\n  color: var(--wa-muted);\n  background: color-mix(in srgb, var(--wa-muted) 12%, transparent);\n}\n\n.data-badge.ok {\n  color: var(--wa-ok);\n  background: color-mix(in srgb, var(--wa-ok) 13%, transparent);\n}\n\n.meter-properties {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 8px;\n}\n\n.meter-property {\n  display: grid;\n  grid-template-columns: 24px minmax(0, 1fr);\n  gap: 2px 7px;\n  min-width: 0;\n  align-items: center;\n  padding: 11px;\n  border-radius: 15px;\n  background: color-mix(in srgb, var(--wa-surface) 65%, var(--wa-card));\n  text-align: left;\n}\n\n.meter-property ha-icon {\n  --mdc-icon-size: 20px;\n  grid-row: 1 / 3;\n  color: var(--wa-blue);\n}\n\n.meter-card.irrigation .meter-property ha-icon {\n  color: var(--wa-irrigation);\n}\n\n.meter-property span {\n  color: var(--wa-muted);\n  font-size: 12px;\n}\n\n.meter-property strong {\n  overflow: hidden;\n  font-size: 12px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.source-card {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 9px;\n}\n\n.source-card > div {\n  display: grid;\n  gap: 4px;\n  min-width: 0;\n  padding: 11px;\n  border-radius: 15px;\n  background: color-mix(in srgb, var(--wa-surface) 65%, var(--wa-card));\n}\n\n.source-card span {\n  color: var(--wa-muted);\n  font-size: 12px;\n}\n\n.source-card strong {\n  overflow: hidden;\n  font-size: 12px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.diagnostic-group h2 {\n  margin: 0 0 12px;\n  font-size: 15px;\n}\n\n.diagnostic-list {\n  display: grid;\n  gap: 8px;\n}\n\n.diagnostic-entity {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) auto;\n  gap: 3px 10px;\n  min-width: 0;\n  padding: 11px;\n  border: 1px solid color-mix(in srgb, var(--wa-ok) 27%, transparent);\n  border-radius: 15px;\n  background: color-mix(in srgb, var(--wa-ok) 7%, var(--wa-card));\n  text-align: left;\n}\n\n.diagnostic-entity.unavailable {\n  border-color: color-mix(in srgb, var(--wa-divider) 82%, transparent);\n  background: color-mix(in srgb, var(--wa-surface) 60%, var(--wa-card));\n}\n\n.diagnostic-entity > div {\n  min-width: 0;\n}\n\n.diagnostic-entity > div strong {\n  display: block;\n  margin-bottom: 3px;\n  font-size: 12px;\n}\n\n.diagnostic-entity code {\n  display: block;\n  overflow: hidden;\n  color: var(--wa-muted);\n  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;\n  font-size: 12px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.diagnostic-entity > span {\n  color: var(--wa-ok);\n  font-size: 12px;\n  font-weight: 750;\n  text-align: right;\n}\n\n.diagnostic-entity.unavailable > span {\n  color: var(--wa-muted);\n}\n\n.diagnostic-entity > small {\n  grid-column: 2;\n  color: var(--wa-muted);\n  font-size: 12px;\n  text-align: right;\n}\n\n.diagnostic-entity pre {\n  grid-column: 1 / -1;\n  max-height: 0;\n  margin: 0;\n  overflow: hidden;\n  color: var(--wa-muted);\n  font-size: 12px;\n  opacity: 0;\n}\n\n.diagnostic-entity:focus pre,\n.diagnostic-entity:hover pre {\n  max-height: 140px;\n  margin-top: 7px;\n  opacity: 1;\n}\n\n.scale-status,\n.panel-toast {\n  position: absolute;\n  z-index: 30;\n  left: 50%;\n  padding: 9px 13px;\n  border-radius: 999px;\n  color: white;\n  background: rgba(22, 28, 35, 0.88);\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.22);\n  font-size: 12px;\n  font-weight: 750;\n  opacity: 0;\n  pointer-events: none;\n  transform: translate(-50%, 10px);\n  transition: opacity 140ms ease, transform 140ms ease;\n}\n\n.scale-status {\n  top: calc(72px + env(safe-area-inset-top));\n}\n\n.panel-toast {\n  bottom: calc(77px + env(safe-area-inset-bottom));\n  max-width: calc(100% - 32px);\n  text-align: center;\n}\n\n.scale-status.visible,\n.panel-toast.visible {\n  opacity: 1;\n  transform: translate(-50%, 0);\n}\n\n@keyframes wa-spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n@media (min-width: 720px) {\n  .page-overview {\n    grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.65fr);\n  }\n\n  .page-overview .system-hero {\n    grid-column: 1 / -1;\n  }\n\n  .page-consumption .chart-card {\n    min-height: 390px;\n  }\n\n  .chart-host,\n  .chart-state,\n  .bar-chart {\n    min-height: 300px;\n    height: 300px;\n  }\n\n  .meters-list {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .diagnostic-list {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n}\n\n@media (max-width: 600px) {\n  .stats-summary-grid {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .stat-total.combined {\n    grid-column: 1 / -1;\n  }\n}\n\n@media (max-width: 390px) {\n  .card,\n  .section-block,\n  .diagnostic-group {\n    padding: 14px;\n    border-radius: 19px;\n  }\n\n  .pressure-card {\n    min-height: 142px;\n    padding: 12px;\n  }\n\n  .threshold-row {\n    grid-template-columns: 62px minmax(0, 1fr);\n  }\n\n  .source-card {\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (max-width: 345px) {\n  .pressure-grid,\n  .meter-reading-grid,\n  .snapshot-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .pressure-card {\n    min-height: 132px;\n  }\n\n  .meter-properties {\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *,\n  *::before,\n  *::after {\n    scroll-behavior: auto !important;\n    transition-duration: 0.01ms !important;\n    animation-duration: 0.01ms !important;\n    animation-iteration-count: 1 !important;\n  }\n\n  .header-action.busy ha-icon {\n    animation: none !important;\n    opacity: 0.62;\n  }\n}\n\n.filter-card, .filter-settings { padding: 20px; margin-bottom: 16px; }\n.filter-card h2, .filter-settings h2 { font-size: 21px; margin: 0 0 12px; }\n.filter-card p, .filter-settings p { font-size: 14px; line-height: 1.5; color: var(--secondary-text-color, #aaa); overflow-wrap: anywhere; }\n.filter-card { border-top: 4px solid #69747d; }\n.filter-card[data-status=\"ok\"] { border-top-color: #43a047; }\n.filter-card[data-status=\"warning\"] { border-top-color: #ff9800; }\n.filter-card[data-status=\"due\"] { border-top-color: #e53935; }\n.filter-form { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin: 16px 0; }\n.filter-form label { display: flex; flex-direction: column; gap: 8px; font-size: 14px; min-width: 0; }\n.filter-form input, .filter-form select { box-sizing: border-box; width: 100%; min-width: 0; min-height: 44px; border: 1px solid #58646c; border-radius: 10px; padding: 10px; font: inherit; color: var(--primary-text-color, #eee); background: var(--card-background-color, #222); }\n.filter-actions { display: flex; flex-wrap: wrap; gap: 12px; }\n.filter-form .filter-checkbox { flex-direction: row; align-items: center; min-height: 44px; }\n.filter-form .filter-checkbox input { width: 24px; min-height: 24px; flex: 0 0 24px; }\n.filter-card button, .filter-settings button { min-height: 44px; padding: 10px 14px; border: 1px solid #008fb5; border-radius: 10px; color: var(--primary-text-color, #eee); background: rgba(0, 188, 212, .12); font-size: 14px; }\n.filter-card button:disabled, .filter-settings button:disabled { opacity: .45; }\n@media (max-width: 440px) { .filter-form { grid-template-columns: minmax(0, 1fr); } }\n\n/* Overview cards own only the domain content inside the canonical shell. */\n.page-overview {\n  width: min(100%, 760px);\n  grid-template-columns: minmax(0, 1fr);\n  gap: 12px;\n}\n.overview-heading h1 { font-size: 25px; line-height: 1.15; margin: 0 0 4px; }\n.overview-heading p { font-size: 14px; line-height: 1.3; margin: 0; color: var(--wa-muted); }\n.overview-card {\n  --overview-status: var(--wa-muted);\n  display: block;\n  width: 100%;\n  padding: 14px 16px;\n  min-width: 0;\n  color: var(--wa-text);\n  text-align: left;\n  cursor: pointer;\n  overflow-wrap: anywhere;\n  border-radius: 18px;\n}\n.overview-card[data-status=\"ok\"], .overview-cartridge[data-status=\"ok\"] { --overview-status: var(--wa-ok); }\n.overview-card[data-status=\"warning\"], .overview-cartridge[data-status=\"warning\"] { --overview-status: var(--wa-warn); }\n.overview-card[data-status=\"due\"], .overview-cartridge[data-status=\"due\"] { --overview-status: var(--wa-bad); }\n.overview-card-heading { display: grid; grid-template-columns: minmax(0, 1fr) auto 20px; gap: 3px 8px; align-items: center; margin-bottom: 12px; }\n.overview-card-title { grid-column: 1 / 3; font-size: 20px; line-height: 1.15; font-weight: 800; }\n.overview-card-heading > ha-icon { grid-column: 3; grid-row: 1 / 3; --mdc-icon-size: 20px; color: var(--wa-muted); }\n.overview-card-subtitle { font-size: 13px; line-height: 1.25; color: var(--wa-muted); }\n.overview-badge { justify-self: end; max-width: 100%; border: 1px solid color-mix(in srgb, var(--overview-status) 64%, transparent); color: var(--overview-status); border-radius: 7px; padding: 2px 6px; font-size: 12px; line-height: 1.25; font-weight: 600; }\n.overview-card-body { display: grid; grid-template-columns: 104px minmax(0, 1fr); align-items: center; gap: 16px; }\n.overview-illustration { display: flex; align-items: center; justify-content: center; width: 104px; height: 128px; }\n.overview-illustration img { display: block; width: 100%; height: 100%; object-fit: contain; user-select: none; -webkit-user-drag: none; }\n.overview-illustration--main img { width: 60px; }\n.overview-illustration--softener { height: 138px; }\n.overview-details { min-width: 0; display: flex; flex-direction: column; align-self: stretch; justify-content: center; border-left: 1px solid var(--wa-divider); padding-left: 16px; }\n.overview-field-label { display: block; font-size: 13px; line-height: 1.3; }\n.overview-value { display: block; font-size: 25px; line-height: 1.2; font-weight: 800; margin-top: 1px; font-variant-numeric: tabular-nums; }\n.overview-date { font-size: 20px; line-height: 1.2; margin: 2px 0; font-weight: 780; font-variant-numeric: tabular-nums; }\n.overview-detail { display: block; color: var(--wa-muted); font-size: 12px; line-height: 1.35; }\n.overview-resource-label { margin-top: 10px; color: var(--wa-muted); }\n.overview-resource { display: block; height: 9px; margin: 6px 0 8px; border-radius: 8px; overflow: hidden; background: color-mix(in srgb, var(--wa-muted) 16%, transparent); border: 1px solid color-mix(in srgb, var(--wa-muted) 45%, transparent); }\n.overview-resource > span { display: block; height: 100%; width: 0; border-radius: inherit; background: var(--overview-status); }\n.overview-salt-label { margin-top: 10px; }\n.overview-gh { display: flex; gap: 5px 12px; justify-content: space-between; flex-wrap: wrap; border-top: 1px solid var(--wa-divider); padding-top: 8px; margin-top: 10px; color: var(--wa-muted); font-size: 12px; line-height: 1.35; }\n.overview-gh > span:last-child { color: var(--wa-text); }\n.overview-cartridges { gap: 10px; }\n.overview-cartridge { --overview-status: var(--wa-muted); display: grid; grid-template-columns: 27px minmax(0, 1fr); align-items: center; gap: 10px; }\n.overview-cartridge > span:last-child { min-width: 0; }\n.overview-cartridge strong { display: block; font-size: 15px; line-height: 1.2; font-weight: 750; }\n.overview-cartridge-number { display: grid; place-items: center; width: 27px; height: 31px; border: 2px solid; border-radius: 8px; font-size: 17px; line-height: 1; font-weight: 750; }\n.overview-cartridge-number--ferrostop { color: #e78a21; }\n.overview-cartridge-number--softening { color: #79a83f; }\n.overview-cartridge-number--postcarbon { color: #bc5db3; }\n.overview-cartridge-status { display: block; font-size: 12px; line-height: 1.3; margin-top: 3px; color: var(--wa-muted); }\n.overview-cartridge[data-status=\"due\"] .overview-cartridge-status,\n.overview-cartridge[data-status=\"warning\"] .overview-cartridge-status { color: var(--overview-status); }\n.overview-notice { --overview-notice-color: var(--wa-muted); display: grid; grid-template-columns: 29px minmax(0, 1fr) 16px; align-items: center; gap: 12px; width: 100%; padding: 12px 14px; border: 1px solid color-mix(in srgb, var(--overview-notice-color) 66%, var(--wa-divider)); border-radius: 16px; background: color-mix(in srgb, var(--overview-notice-color) 11%, var(--wa-card)); text-align: left; cursor: pointer; }\n.overview-notice[data-status=\"warning\"] { --overview-notice-color: var(--wa-warn); }\n.overview-notice[data-status=\"due\"] { --overview-notice-color: var(--wa-bad); }\n.overview-notice > ha-icon { color: var(--overview-notice-color); --mdc-icon-size: 28px; }\n.overview-notice > ha-icon:last-child { --mdc-icon-size: 17px; }\n.overview-notice-copy { display: block; min-width: 0; overflow-wrap: anywhere; }\n.overview-notice-copy strong { display: block; font-size: 15px; line-height: 1.25; color: var(--overview-notice-color); }\n.overview-notice-copy > span { display: block; font-size: 12px; line-height: 1.35; margin-top: 3px; color: var(--wa-text); }\n@media (max-width: 390px) {\n  .overview-card { padding: 12px; }\n  .overview-card-title { font-size: 19px; }\n  .overview-card-body { grid-template-columns: 80px minmax(0, 1fr); gap: 12px; }\n  .overview-illustration { width: 80px; height: 118px; }\n  .overview-illustration--softener { height: 130px; }\n  .overview-illustration--main img { width: 48px; }\n  .overview-details { padding-left: 12px; }\n  .overview-cartridge { gap: 7px; grid-template-columns: 24px minmax(0, 1fr); }\n  .overview-cartridge-number { width: 24px; height: 29px; }\n  .overview-cartridge strong { font-size: 14px; }\n}\n@media (max-width: 345px) {\n  .overview-card-heading { grid-template-columns: minmax(0, 1fr) auto 20px; gap: 4px 5px; }\n  .overview-card-subtitle { font-size: 12px; }\n  .overview-badge { padding: 2px 4px; }\n  .overview-card-body { grid-template-columns: 66px minmax(0, 1fr); gap: 10px; }\n  .overview-illustration { width: 66px; }\n  .overview-details { padding-left: 10px; }\n}\n";
// END custom_components/water_treatment/frontend/src/styles.css
const VIEW_STORAGE_KEY = "nikas.water-treatment.view.v1";
const VALID_VIEWS = new Set(TREATMENT_APP.tabs.map(tab => tab[0]));

function escapeHtml(value) {
  return String(value == null ? "" : value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function safeReturnRoute(value) {
  return normalizeNikasBaseRoute(value);
}

function resolveReturnRoute(panel) {
  return captureNikasShellReturnRoute({
    panelId: "water-treatment",
    parentRoute: panel._panel && panel._panel.config
      ? panel._panel.config.parent_route
      : null,
    safeReturnRoute: TREATMENT_APP.safeReturnRoute,
  });
}

function navigateToSource(panel) {
  const route = safeReturnRoute(panel._returnRoute) || TREATMENT_APP.safeReturnRoute;
  navigateNikasShell(route);
}

function numeric(value) {
  if (value == null || BAD_STATES.has(String(value).trim().toLowerCase())) return null;
  const result = Number(String(value).replace(",", "."));
  return Number.isFinite(result) ? result : null;
}

function loadStoredChoice(key, valid, fallback) {
  try {
    const value = localStorage.getItem(key);
    return valid.has(value) ? value : fallback;
  } catch (_error) {
    return fallback;
  }
}

function saveStoredChoice(key, value) {
  try {
    localStorage.setItem(key, value);
  } catch (_error) {
    // Local persistence is optional.
  }
}


class NikaSWaterTreatmentPanel extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    this._filterData = null;
    this._filterLoadError = false;
    this._filterDisconnected = false;
    this._filterBusy = false;
    this._filterLoadPromise = null;
    this._saltDraftRevision = 0;
    this._filterControlEdits = new Map();
    this._filterDirtyControls = new Set();
    this._filterDraftBases = new Map();
    this._filterTimer = null;
    this._hass = null;
    this._panel = null;
    this._shellMounted = false;
    this._patchQueued = false;
    this._returnRoute = null;
    this._view = loadStoredChoice(VIEW_STORAGE_KEY, VALID_VIEWS, TREATMENT_APP.preferredView);
    this._views = new Map();
    this._refreshing = false;
    this._refreshToken = 0;
    this._refreshDelayTimer = null;
    this._refreshResultTimer = null;
    this._toastTimer = null;
    this._removeScrollBoundaryGuard = null;
    this._hold = null;
    this._holdFiredUntil = 0;
  }

  set hass(value) {
    const disconnected = value?.connection?.connected === false;
    if (this._filterDisconnected && !disconnected) this._filterData = null;
    this._filterDisconnected = disconnected;
    this._hass = value;
    this._queuePatch();
  }

  get hass() {
    return this._hass;
  }

  set panel(value) {
    this._panel = value;
    const preferred = value && value.config ? value.config.preferred_view : null;
    if (VALID_VIEWS.has(preferred) && !this._shellMounted) this._view = preferred;
    this._queuePatch();
  }

  get panel() {
    return this._panel;
  }

  connectedCallback() {
    this._mountShell();
    this._queuePatch();
  }

  disconnectedCallback() {
    window.clearTimeout(this._filterTimer);
    this._filterTimer = null;
    this._refreshToken += 1;
    this._refreshing = false;
    if (this._refreshDelayTimer !== null) {
      window.clearTimeout(this._refreshDelayTimer.id);
      this._refreshDelayTimer.resolve();
      this._refreshDelayTimer = null;
    }
    if (this._refreshResultTimer !== null) {
      window.clearTimeout(this._refreshResultTimer);
      this._refreshResultTimer = null;
    }
    if (this._toastTimer !== null) {
      window.clearTimeout(this._toastTimer);
      this._toastTimer = null;
    }
    const previousToast = this.shadowRoot.querySelector(".panel-toast");
    if (previousToast) previousToast.classList.remove("visible");
    if (this._removeScrollBoundaryGuard) {
      this._removeScrollBoundaryGuard();
      this._removeScrollBoundaryGuard = null;
    }
    this._cancelHold();
  }

  _config() {
    const config = this._panel && this._panel.config ? this._panel.config : {};
    const tabs = Array.isArray(config.tabs) && config.tabs.length
      ? config.tabs.slice(0, 5)
      : TREATMENT_APP.tabs;
    return {
      title: config.title || TREATMENT_APP.title,
      uiVersion: /^\d+\.\d+\.\d+$/.test(String(config.ui_version || ""))
        ? String(config.ui_version)
        : TREATMENT_APP.uiVersion,
      tabs: tabs,
      entities: Object.assign({}, TREATMENT_APP.entities, config.entities || {}),
    };
  }

  _mountShell() {
    if (this._shellMounted || !this.isConnected) return;
    if (this._returnRoute == null) this._returnRoute = resolveReturnRoute(this);
    const config = this._config();
    this.shadowRoot.innerHTML = '<style>' + TREATMENT_CSS + nikasShellV2Styles() + '</style>'
      + '<div class="app-shell nikas-shell">'
      + '<header class="app-header nikas-shell__header">'
      + '<button type="button" class="header-action nikas-shell__side-action" id="menu" aria-label="Меню Home Assistant">'
      + '<ha-icon icon="mdi:menu"></ha-icon></button>'
      + '<button type="button" class="header-title nikas-shell__title" id="return-source" aria-label="Вернуться на главную панель">'
      + '<strong>' + escapeHtml(config.title) + '</strong>'
      + '<small>UI v' + escapeHtml(config.uiVersion) + '</small></button>'
      + '<button type="button" class="header-action nikas-shell__side-action nikas-shell__side-action--right" id="refresh" aria-label="Обновить">'
      + '<ha-icon icon="mdi:refresh"></ha-icon></button>'
      + '</header>'
      + '<main class="canvas-viewport nikas-shell__viewport" aria-label="Рабочая область панели">'
      + '<div class="work-canvas nikas-shell__canvas"><div class="work-content nikas-shell__content"></div></div></main>'
      + '<nav class="tabbar nikas-shell__tabs" aria-label="Разделы"></nav>'
      + '<div class="scale-status" role="status" aria-live="polite">Масштаб 100%</div>'
      + '<div class="panel-toast" role="status" aria-live="polite"></div>'
      + '</div>';
    this._removeScrollBoundaryGuard = createNikasShellScrollBoundaryGuard({
      host: this,
      viewport: this.shadowRoot.querySelector(".canvas-viewport"),
    });
    this._bindShellEvents();
    this._renderTabBar();
    VALID_VIEWS.forEach(view => this._ensureView(view));
    this._activateView(this._view, false);
    this._shellMounted = true;
    window.requestAnimationFrame(() => {
      if (this.isConnected) {
        window.NikasPanelZoom && window.NikasPanelZoom.attach
          ? window.NikasPanelZoom.attach(this, { min: 0.75, max: 2.0 })
          : null;
      }
    });
  }

  _bindShellEvents() {
    this.shadowRoot.addEventListener("click", (event) => {
      const button = event.target && event.target.closest ? event.target.closest("button") : null;
      if (!button) return;
      if (Date.now() < this._holdFiredUntil) {
        event.preventDefault();
        event.stopPropagation();
        return;
      }
      if (button.id === "menu") {
        this.dispatchEvent(new CustomEvent("hass-toggle-menu", { bubbles: true, composed: true }));
      } else if (button.id === "return-source") {
        navigateToSource(this);
      } else if (button.id === "refresh") {
        this._refresh();
      } else if (button.dataset.filterAction) {
        this._filterAction(button);
      } else if (button.dataset.view) {
        this._activateView(button.dataset.view, true);
        if (button.dataset.overviewFilter) this._focusOverviewFilter(button.dataset.overviewFilter);
      }
    });

    this.shadowRoot.addEventListener("input", (event) => {
      if (event.target && event.target.id === "salt-kg") this._saltDraftRevision += 1;
      if (event.target && event.target.id) this._recordFilterEdit(event.target.id);
    });
    this.shadowRoot.addEventListener("change", (event) => {
      if (event.target && event.target.id) this._recordFilterEdit(event.target.id);
      if (event.target.id === "filter-profile") {
        const profile = event.target.value;
        this.shadowRoot.querySelector("#filter-volume").value = profile === "wound" ? 200 : 100;
        this.shadowRoot.querySelector("#filter-months").value = 6;
        this._recordFilterEdit('filter-volume');
        this._recordFilterEdit('filter-months');
      }
    });
    this.shadowRoot.addEventListener("pointerdown", (event) => this._beginHold(event));
    this.shadowRoot.addEventListener("pointermove", (event) => this._moveHold(event));
    ["pointerup", "pointercancel", "pointerleave"].forEach((name) => {
      this.shadowRoot.addEventListener(name, () => this._cancelHold());
    });
  }

  _beginHold(event) {
    const target = event.target && event.target.closest
      ? event.target.closest("[data-entity]")
      : null;
    if (!target || !target.dataset.entity) return;
    this._cancelHold();
    this._hold = {
      target: target,
      entityId: target.dataset.entity,
      x: event.clientX,
      y: event.clientY,
      timer: window.setTimeout(() => {
        if (!this._hold) return;
        this._holdFiredUntil = Date.now() + 650;
        this.dispatchEvent(new CustomEvent("hass-more-info", {
          detail: { entityId: this._hold.entityId },
          bubbles: true,
          composed: true,
        }));
        this._cancelHold();
      }, 550),
    };
  }

  _moveHold(event) {
    if (!this._hold) return;
    if (Math.hypot(event.clientX - this._hold.x, event.clientY - this._hold.y) > 8) {
      this._cancelHold();
    }
  }

  _cancelHold() {
    if (this._hold && this._hold.timer) window.clearTimeout(this._hold.timer);
    this._hold = null;
  }

  _renderTabBar() {
    const nav = this.shadowRoot.querySelector(".tabbar");
    if (!nav || nav.childElementCount) return;
    const tabs = this._config().tabs;
    nav.style.setProperty("--nikas-shell-tab-count", String(Math.max(1, tabs.length)));
    tabs.forEach((tab) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "nikas-shell__tab";
      button.dataset.view = tab[0];
      button.setAttribute("aria-label", tab[2]);
      button.innerHTML = '<ha-icon icon="' + escapeHtml(tab[1]) + '"></ha-icon>'
        + '<small>' + escapeHtml(tab[2]) + '</small>';
      nav.appendChild(button);
    });
  }

  _viewMarkup(view) {
    if (view === "overview") return waterOverviewMarkup(this._config().uiVersion);
    if (view === "softener") return this._saltMarkup() + waterSoftenerMarkup();
    if (view === "quality") return waterQualityMarkup();
    return this._filtersMarkup();
  }

  _ensureView(view) {
    if (this._views.has(view)) return this._views.get(view);
    const root = document.createElement("section");
    root.className = "page page-" + view;
    root.dataset.viewRoot = view;
    root.hidden = true;
    root.innerHTML = this._viewMarkup(view);
    this.shadowRoot.querySelector(".work-content").appendChild(root);
    this._views.set(view, root);
    this._applyEntityTargets(root);
    return root;
  }

  _applyEntityTargets(root) {
    const entities = this._config().entities;
    root.querySelectorAll("[data-entity-role]").forEach((node) => {
      const entityId = entities[node.dataset.entityRole];
      if (entityId) node.dataset.entity = entityId;
      else node.removeAttribute("data-entity");
    });
  }

  _activateView(view, fromUser) {
    const next = VALID_VIEWS.has(view) ? view : TREATMENT_APP.preferredView;
    const root = this._ensureView(next);
    this._views.forEach((node, key) => {
      node.hidden = key !== next;
    });
    this._view = next;
    saveStoredChoice(VIEW_STORAGE_KEY, next);
    this.shadowRoot.querySelectorAll(".tabbar [data-view]").forEach((button) => {
      const active = button.dataset.view === next;
      button.classList.toggle("active", active);
      button.setAttribute("aria-current", active ? "page" : "false");
    });
    if (fromUser) {
      const controller = window.NikasPanelZoom && window.NikasPanelZoom.attach
        ? window.NikasPanelZoom.attach(this)
        : null;
      if (controller && controller.resetPosition) controller.resetPosition();
      else this.shadowRoot.querySelector(".canvas-viewport").scrollTop = 0;
    }
    this._loadFilters();
    this._queuePatch();
  }

  _focusOverviewFilter(key) {
    if (!['main', 'ferrostop', 'softening', 'postcarbon'].includes(key)) return;
    window.requestAnimationFrame(() => {
      if (this._view !== 'filters' || !this.isConnected) return;
      const card = this.shadowRoot.querySelector('[data-filter-card="' + key + '"]');
      const viewport = this.shadowRoot.querySelector('.canvas-viewport');
      if (!card || !viewport) return;
      card.setAttribute('tabindex', '-1');
      card.focus({preventScroll: true});
      viewport.scrollTop += card.getBoundingClientRect().top - viewport.getBoundingClientRect().top - 12;
    });
  }

  _filtersMarkup() {
    const cards = [["main", "Магистральный · профиль BB20"], ["ferrostop", "Профиль ЭКСПЕРТ Ферростоп"],
      ["softening", "ЭКСПЕРТ Смягчение"], ["postcarbon", "ЭКСПЕРТ Посткарбон"]];
    const input = (id, label, type, extra) => '<label>' + label + '<input id="' + id
      + '" type="' + type + '" ' + (extra || '') + '></label>';
    return '<section class="card filter-settings"><h2>Фильтры питьевой воды</h2>'
      + '<p>Магистральный — по счётчику питьевой воды. Полив не учитывается.</p>'
      + '<p>Профили BB20 и ЭКСПЕРТ Комплекс выбраны для обслуживания; маркировку установленных картриджей нужно сверить отдельно.</p>'
      + '<p data-filter-message role="status">Загрузка настроек…</p>'
      + '<button type="button" data-filter-action="reload">Обновить данные фильтров</button></section>'
      + cards.map(([key, title]) => '<section class="card filter-card" data-filter-card="' + key + '">'
        + '<h2>' + title + '</h2><strong data-filter-status="' + key + '">Нет данных</strong>'
        + '<p data-filter-detail="' + key + '"></p>'
        + '<div class="filter-form">' + input('date-' + key, 'Дата последней замены', 'date')
        + (key === 'main' ? input('baseline-main', 'Показание при замене, м³', 'number', 'min="0" step="0.001"') : '')
        + '</div><div class="filter-actions"><button type="button" data-filter-action="record" data-filter="' + key + '">Сохранить дату'
        + '</button><button type="button" data-filter-action="replace" data-filter="' + key + '">Картридж заменён</button></div></section>').join('')
      + '<section class="card filter-settings"><h2>Настройки магистрального фильтра</h2><div class="filter-form">'
      + '<label>Профиль<select id="filter-profile"><option value="mechanical">Механика BB20 · 5 мкм</option>'
      + '<option value="wound">Нитка BB20 · 10 мкм</option></select></label>'
      + input('filter-volume', 'Ресурс, м³', 'number', 'min="0.001" max="10000" step="0.001" required')
      + input('filter-months', 'Срок, месяцев', 'number', 'min="0.5" max="12" step="0.5" required')
      + '<label>Контроль<select id="filter-mode"><option value="volume">По объёму</option><option value="time">По времени</option>'
      + '<option value="both">Что наступит раньше</option></select></label></div>'
      + '<p>Профили БАРЬЕР: механика — 100 м³; нитка — 200 м³. Срок 6 месяцев для нитки — начальная настройка, не подтверждённая рекомендация производителя. Объём и срок можно изменить.</p></section>'
      + '<section class="card filter-settings"><h2>Настройки ЭКСПЕРТ Комплекс</h2><div class="filter-form">'
      + input('filter-people', 'Количество пользователей', 'number', 'min="1" max="20" step="1" required')
      + input('filter-hardness', 'На входе БАРЬЕР после Ёлки, °Ж (мг-экв/л)', 'number', 'min="0.0001" max="100" step="0.0001"')
      + '<label>Срок смягчения<select id="filter-auto"><option value="auto">По таблице БАРЬЕР</option>'
      + '<option value="manual">Задать вручную</option></select></label>'
      + input('months-ferrostop', 'Ферростоп, месяцев', 'number', 'min="0.5" max="12" step="0.5" required')
      + input('months-softening', 'Смягчение вручную, месяцев', 'number', 'min="0.5" max="12" step="0.5" required')
      + input('months-postcarbon', 'Посткарбон, месяцев', 'number', 'min="0.5" max="12" step="0.5" required')
      + '</div><p>Расчёт для 1–3 пользователей и жёсткости до 5 мг-экв/л; не более 6 месяцев. Вне таблицы задайте срок вручную. Начальные сроки Ферростопа и Посткарбона — 6 месяцев. Полмесяца = 15 дней.</p>'
      + '<button type="button" data-filter-action="settings">Сохранить настройки</button>'
      + '<p>Настройки не сбрасывают даты и расход. Изменять их может администратор HA.</p></section>';
  }

  _loadFilters(fill) {
    if (this._filterLoadPromise) return this._filterLoadPromise;
    if (this._filterBusy || !this._hass || typeof this._hass.callWS !== "function") return Promise.resolve();
    this._filterLoadPromise = this._readFilters(fill).finally(() => {
      this._filterLoadPromise = null;
      this._scheduleFiltersRefresh();
    });
    return this._filterLoadPromise;
  }

  _scheduleFiltersRefresh() {
    window.clearTimeout(this._filterTimer);
    this._filterTimer = null;
    if (this.isConnected) {
      this._filterTimer = window.setTimeout(() => this._loadFilters(), 30000);
    }
  }

  async _readFilters(fill) {
    const guard = {edits: new Map(this._filterControlEdits), ids: null, preserveDrafts: true};
    try {
      const data = await this._withTimeout(this._hass.callWS({ type: "water_treatment/filters" }), 15000);
      this._filterLoadError = false;
      this._filterData = data;
      this._paintFilters(true, guard);
      this._setText("[data-filter-message]", "Данные водоподготовки актуальны");
    } catch (error) {
      this._filterData = null;
      this._filterLoadError = true;
      paintWaterOverview(this);
      this._setText("[data-filter-message]", "Не удалось получить данные: " + (error.message || String(error)));
      for (const selector of ['[data-salt-message]', '[data-treatment-message]', '[data-gh-message]']) {
        this._setText(selector, "Не удалось получить данные: " + (error.message || String(error)));
      }
      this.shadowRoot.querySelectorAll("[data-filter-status]").forEach(node => { node.textContent = "Нет данных"; });
      this.shadowRoot.querySelectorAll("[data-filter-detail]").forEach(node => { node.textContent = ""; });
      this._setText('[data-salt-status]', 'Нет данных');
      this._setText('[data-salt-detail]', '');
      this._setText('[data-salt-balance]', 'Нет данных');
      this._setText('[data-salt-coverage]', '');
      this._setText('[data-treatment-summary]', 'Нет данных');
      this._setText('[data-gh-history]', 'Нет данных');
    }
  }

  _saltMarkup() {
    return '<section class="card filter-card" data-salt-card><h2>Ёлка — запас соли</h2>'
      + '<p>WSC-0,5-Rx-(SC) · кабинетный умягчитель</p><strong data-salt-status>Нет данных</strong>'
      + '<p data-salt-detail></p><p>Состояние по ручной проверке. Учтённая масса и оценка по дозам показаны отдельно.</p>'
      + '<div class="filter-form"><label>Досыпано, кг<input id="salt-kg" type="number" min="0.1" max="100" step="0.1"></label>'
      + '<label>Запас при проверке<select id="salt-level"><option value="enough">Достаточно</option>'
      + '<option value="low">Мало — досыпать</option><option value="empty">Соль закончилась</option></select></label></div>'
      + '<div class="filter-actions"><button type="button" data-filter-action="salt_topup">Записать досыпку</button>'
      + '<button type="button" data-filter-action="salt_check">Запас проверен</button></div>'
      + '<p data-salt-message role="status" aria-live="polite">Введите массу и нажмите «Записать досыпку».</p>'
      + waterSaltLedgerMarkup()
      + '<details><summary>Настройки и история соли</summary><div class="filter-form">'
      + '<label>Проверять каждые, дней<input id="salt-days" type="number" min="1" max="90" step="1"></label>'
      + '<label>Соль за регенерацию, кг<input id="salt-dose" type="number" min="0.1" max="20" step="0.1"></label>'
      + '<label>Основание дозы<select id="salt-dose-basis"><option value="assumed">Предварительная оценка</option><option value="measured">Измерена при калибровке</option><option value="legacy_unverified">Унаследована, не проверена</option></select></label></div>'
      + '<button type="button" data-filter-action="salt_settings">Сохранить настройки соли</button>'
      + '<p>Настройки меняют дозу и напоминание; досыпку записывает отдельная кнопка выше. Для старой версии 1 кг/цикл предварителен. Современные 1,5 кг автоматически не применяются. Интервал проверки по умолчанию 6 дней.</p>'
      + '<p data-salt-history></p></details></section>';
  }

  _paintSalt(fill, guard) {
    const cfg = this._filterData && this._filterData.settings.salt;
    const state = this._filterData && this._filterData.salt_status;
    if (!cfg || !state) return;
    const labels = {unknown:'Запас ещё не проверен',ok:'По последней проверке: достаточно',check:'Пора проверить соль',low:'Мало соли — досыпать',empty:'Соль закончилась — досыпать'};
    this._setText('[data-salt-status]',labels[state.state]);
    const details = [];
    if (cfg.last_checked) details.push('Проверка: ' + cfg.last_checked.split('-').reverse().join('.'));
    if (state.days != null) details.push(state.days > 0 ? 'До проверки: ' + state.days + ' дн.' : 'Проверка требуется');
    if (cfg.last_added) details.push('Досыпка: ' + cfg.last_added.split('-').reverse().join('.') + ', ' + cfg.last_added_kg + ' кг');
    this._setText('[data-salt-detail]',details.join(' · '));
    this._setText('[data-salt-history]',cfg.history.slice(-30).reverse().map(waterSaltEventText).join(' • ') || 'История пока пуста');
    const card=this.shadowRoot.querySelector('[data-salt-card]');
    if(card) card.dataset.status = state.state === 'ok' ? 'ok' : ['low','empty'].includes(state.state) ? 'due' : state.state === 'check' ? 'warning' : 'unknown';
    if(fill) {
      const values={'salt-days':cfg.check_days,'salt-dose':cfg.dose,'salt-level':cfg.level === 'unknown' ? 'enough' : cfg.level};
      Object.entries(values).forEach(([id,value]) => this._fillFilterControl(id,value,guard));
    }
  }

  _recordFilterEdit(id) {
    this._filterControlEdits.set(id, (this._filterControlEdits.get(id) || 0) + 1);
    this._filterDirtyControls.add(id);
    const section = waterDraftSection(id);
    if (section && this._filterData && !this._filterDraftBases.has(section)) {
      this._filterDraftBases.set(section, {revision: this._filterData.revision,
        fingerprint: waterSettingsFingerprint(this._filterData.settings,section)});
    }
  }

  _filterEditingRevision(action) {
    const base = this._filterDraftBases.get(action);
    if (base && base.fingerprint !== waterSettingsFingerprint(this._filterData?.settings,action)) return base.revision;
    return this._filterData && this._filterData.revision;
  }

  _fillFilterControl(id, value, guard) {
    if (guard && ((guard.ids && !guard.ids.has(id)) || (this._filterControlEdits.get(id) || 0) !== (guard.edits.get(id) || 0))) return;
    if (guard && guard.preserveDrafts) {
      const section = waterDraftSection(id);
      if (this._filterDirtyControls.has(id) || (section && Array.from(this._filterDirtyControls)
        .some(dirty => waterDraftSection(dirty) === section))) return;
    }
    const node = this.shadowRoot.querySelector('#' + id);
    if (!node) return;
    if (typeof value === 'boolean') node.checked = value;
    else node.value = value == null ? '' : value;
  }

  _paintFilters(fill, guard) {
    paintWaterOverview(this);
    const data = this._filterData;
    if (!data || !this._views.has("filters")) return;
    const cfg = data.settings;
    const labels = { unconfigured: "Укажите дату замены", unknown: "Нет данных для расчёта",
      due: "Заменить картридж", warning: "Скоро замена", ok: "Ресурс в норме" };
    Object.entries(data.status).forEach(([key, item]) => {
      this._setText('[data-filter-status="' + key + '"]', labels[item.state]);
      const parts = [];
      if (item.days != null) parts.push(item.days < 0 ? 'Просрочено дней: ' + Math.abs(item.days) : 'Осталось дней: ' + item.days);
      if (item.deadline) parts.push('Замена до: ' + item.deadline.split('-').reverse().join('.'));
      if (item.used != null) parts.push('После замены: ' + this._formatNumber(item.used, 3) + ' м³; осталось: '
        + this._formatNumber(Math.max(0, item.remaining), 3) + ' м³ (' + Math.round(item.percent) + '%)');
      if (key === 'main' && item.used == null) parts.push('Нет расхода: проверьте счётчик и показание при замене');
      if (key === 'softening' && cfg.softening_auto && cfg.cartridges.softening.months == null) parts.push('Укажите жёсткость или задайте срок вручную');
      this._setText('[data-filter-detail="' + key + '"]', parts.join(' · '));
      const card = this.shadowRoot.querySelector('[data-filter-card="' + key + '"]');
      if (card) card.dataset.status = item.state;
    });
    if (fill) {
      const values = { 'filter-profile': cfg.main.profile, 'filter-volume': cfg.main.volume,
        'filter-months': cfg.main.months, 'filter-mode': cfg.main.mode, 'filter-people': cfg.people,
        'filter-hardness': cfg.hardness, 'filter-auto': cfg.softening_auto ? 'auto' : 'manual',
        'date-main': cfg.main.date, 'baseline-main': cfg.main.baseline };
      Object.entries(cfg.cartridges).forEach(([key, item]) => {
        values['date-' + key] = item.date;
        values['months-' + key] = item.months || 6;
      });
      Object.entries(values).forEach(([id, value]) => this._fillFilterControl(id,value,guard));
      this._filtersFilled = true;
    }
    this._paintSalt(fill, guard);
    paintWaterTreatment(this, fill, guard);
    if (fill && (!guard || (!guard.ids && !guard.preserveDrafts))) {
      for (const [section,ids] of [['settings',WATER_FILTER_SETTING_IDS],['treatment_settings',WATER_TREATMENT_SETTING_IDS],['salt_settings',['salt-days','salt-dose','salt-dose-basis']]]) {
        if (!guard || ids.every(id=>(this._filterControlEdits.get(id)||0)===(guard.edits.get(id)||0))) this._filterDraftBases.delete(section);
      }
    }
    const admin = this._hass.user && this._hass.user.is_admin;
    this.shadowRoot.querySelectorAll('[data-filter-action]').forEach(button => {
      button.disabled = button.dataset.filterAction !== 'reload' && !admin;
    });
  }

  _filterMessage(message, action) {
    this._setText('[data-filter-message]', message);
    if (action.startsWith('salt_')) this._setText('[data-salt-message]', message);
    if (action.startsWith('treatment_')) this._setText('[data-treatment-message]', message);
    if (action === 'treatment_gh') this._setText('[data-gh-message]', message);
  }

  async _filterAction(button) {
    const action = button.dataset.filterAction;
    if (action === 'reload') { this._filtersFilled = false; return this._loadFilters(true); }
    if (this._filterBusy) return;
    const root = this.shadowRoot;
    const editingRevision = this._filterEditingRevision(action);
    const saltDraftRevision = this._saltDraftRevision;
    const value = id => root.querySelector('#' + id).value;
    let payload;
    if (action.startsWith('treatment_') || ['salt_service','salt_remove','salt_regeneration'].includes(action)) {
      try { payload = waterTreatmentPayload(root, action); }
      catch (error) { this._filterMessage('Не сохранено: ' + error.message, action); return; }
      if (payload === null) return;
    } else if (action.startsWith('salt_')) {
      const ids = action === 'salt_settings' ? ['salt-days','salt-dose'] : action === 'salt_topup' ? ['salt-kg'] : [];
      for (const id of ids) { const node=root.querySelector('#'+id); if (!node.value || !node.reportValidity()) { this._filterMessage('Заполните параметры соли',action); return; } }
      payload = action === 'salt_settings' ? {check_days:Number(value('salt-days')),dose:Number(value('salt-dose'))}
        : action === 'salt_topup' ? {kg:Number(value('salt-kg'))} : {level:value('salt-level')};
      const basis = root.querySelector('#salt-dose-basis');
      if (action === 'salt_settings' && basis) payload.dose_basis = basis.value;
    } else if (action === 'settings') {
      for (const id of WATER_FILTER_SETTING_IDS) {
        const node = root.querySelector('#' + id);
        if (!node.reportValidity()) return;
      }
      payload = { main: { profile: value('filter-profile'), volume: Number(value('filter-volume')),
        months: Number(value('filter-months')), mode: value('filter-mode') }, people: Number(value('filter-people')),
        hardness: value('filter-hardness') ? Number(value('filter-hardness')) : null,
        softening_auto: value('filter-auto') === 'auto',
        months: Object.fromEntries(['ferrostop', 'softening', 'postcarbon'].map(key => [key, Number(value('months-' + key))])) };
    } else {
      payload = { filter: button.dataset.filter };
      if (action === 'record') {
        payload.date = value('date-' + payload.filter);
        if (!payload.date) { this._setText('[data-filter-message]', 'Укажите дату замены'); return; }
        if (payload.filter === 'main') {
          if (!value('baseline-main')) { this._setText('[data-filter-message]', 'Укажите показание при замене'); return; }
          payload.baseline = Number(value('baseline-main'));
        }
      }
      if (action === 'replace' && !window.confirm('Картридж заменён сегодня? Начать новый отсчёт ресурса?')) return;
    }
    const fillGuard = {edits: new Map(this._filterControlEdits), ids: waterFilterFillIds(action,payload)};
    this._filterBusy = true;
    button.disabled = true;
    window.clearTimeout(this._filterTimer);
    this._filterMessage('Сохраняю…', action);
    try {
      // A top-up appends to the current history. Settings edits retain the revision
      // they were based on, so a background read cannot hide another user's edit.
      // The write guard spans this wait so a second press cannot duplicate a top-up.
      if (this._filterLoadPromise) await this._filterLoadPromise;
      if (!this._filterData) throw new Error('Обновите данные фильтров и повторите запись');
      const revision = action === 'salt_topup' || editingRevision == null
        ? this._filterData.revision : editingRevision;
      this._filterData = await this._withTimeout(this._hass.callWS({ type: 'water_treatment/filters', action,
        payload, revision }), 15000);
      this._filterLoadError = false;
      this._paintFilters(true, fillGuard);
      for (const id of fillGuard.ids) {
        if ((this._filterControlEdits.get(id) || 0) === (fillGuard.edits.get(id) || 0)) this._filterDirtyControls.delete(id);
      }
      const fingerprint = waterSettingsFingerprint(this._filterData.settings,action);
      if (fingerprint != null) {
        if (Array.from(this._filterDirtyControls).some(id => waterDraftSection(id) === action)) {
          this._filterDraftBases.set(action,{revision:this._filterData.revision,fingerprint});
        } else this._filterDraftBases.delete(action);
      }
      if (action === 'salt_topup') {
        const input = root.querySelector('#salt-kg');
        if (this._saltDraftRevision === saltDraftRevision && Number(input.value) === payload.kg) input.value = '';
      }
      resetWaterTreatmentEvent(this, action, fillGuard);
      this._filterMessage(action === 'salt_topup'
        ? 'Сохранено: досыпано ' + this._formatNumber(payload.kg, 1) + ' кг. Дата и масса показаны выше.'
        : 'Сохранено', action);
    } catch (error) {
      this._filterMessage('Не сохранено: ' + (error.message || String(error)), action);
    } finally {
      this._filterBusy = false;
      button.disabled = false;
      this._scheduleFiltersRefresh();
    }
  }

  _queuePatch() {
    if (this._patchQueued) return;
    this._patchQueued = true;
    const schedule = window.requestAnimationFrame || function (callback) { queueMicrotask(callback); };
    schedule(() => {
      this._patchQueued = false;
      this._patch();
    });
  }

  _patch() {
    this._mountShell();
    if (!this._shellMounted) return;
    const config = this._config();
    this._setText(".header-title strong", config.title);
    this._setText(".header-title small", "UI v" + config.uiVersion);
    paintWaterOverview(this);
    if (!this._filterData && !this._filterLoadPromise && !this._filterBusy) this._loadFilters();
    window.NikasPanelZoom && window.NikasPanelZoom.attach
      ? window.NikasPanelZoom.attach(this, { min: 0.75, max: 2.0 }).bind() : null;
  }

  _setText(selector, value, root) {
    const scope = root || this.shadowRoot;
    const node = scope.querySelector(selector);
    const text = String(value == null ? "" : value);
    if (node && node.textContent !== text) node.textContent = text;
  }

  _formatNumber(value, digits) {
    if (!Number.isFinite(value)) return "—";
    return new Intl.NumberFormat(this._hass && this._hass.locale
      ? this._hass.locale.language || "ru"
      : "ru", {
      minimumFractionDigits: digits,
      maximumFractionDigits: digits,
    }).format(value);
  }

  _withTimeout(promise, milliseconds) {
    return new Promise((resolve, reject) => {
      const timer = window.setTimeout(() => reject(new Error("Recorder timeout")), milliseconds);
      Promise.resolve(promise).then((value) => {
        window.clearTimeout(timer);
        resolve(value);
      }, (error) => {
        window.clearTimeout(timer);
        reject(error);
      });
    });
  }

  _setRefreshVisual(state) {
    const button = this.shadowRoot.querySelector("#refresh");
    if (!button) return;
    const icon = button.querySelector("ha-icon");
    const details = {
      idle: ["mdi:refresh", "Обновить", "var(--primary-color, #03a9d9)"],
      busy: ["mdi:refresh", "Обновление данных", "var(--primary-color, #03a9d9)"],
      success: ["mdi:check", "Данные обновлены", "#43a047"],
      error: ["mdi:alert-circle-outline", "Ошибка обновления", "#e53935"],
    }[state] || ["mdi:refresh", "Обновить", "var(--primary-color, #03a9d9)"];
    button.classList.toggle("busy", state === "busy");
    button.classList.toggle("success", state === "success");
    button.classList.toggle("error", state === "error");
    button.disabled = state === "busy";
    button.setAttribute("aria-label", details[1]);
    button.setAttribute("aria-busy", String(state === "busy"));
    button.style.color = details[2];
    if (icon) icon.setAttribute("icon", details[0]);
  }

  _delay(milliseconds) {
    return new Promise((resolve) => {
      const timer = {
        id: null,
        resolve: resolve,
      };
      timer.id = window.setTimeout(() => {
        if (this._refreshDelayTimer === timer) this._refreshDelayTimer = null;
        resolve();
      }, milliseconds);
      this._refreshDelayTimer = timer;
    });
  }

  async _refresh() {
    if (this._refreshing) return false;
    if (this._refreshResultTimer !== null) {
      window.clearTimeout(this._refreshResultTimer);
      this._refreshResultTimer = null;
    }
    if (this._toastTimer !== null) {
      window.clearTimeout(this._toastTimer);
      this._toastTimer = null;
    }
    const previousToast = this.shadowRoot.querySelector(".panel-toast");
    if (previousToast) previousToast.classList.remove("visible");
    const token = ++this._refreshToken;
    this._refreshing = true;
    this._setRefreshVisual("busy");
    const startedAt = typeof performance !== "undefined" && performance.now
      ? performance.now()
      : Date.now();
    const entities = Array.from(new Set(Object.values(this._config().entities).filter(Boolean)));
    let success = false;
    try {
      if (!entities.length || !this._hass || typeof this._hass.callService !== "function") {
        throw new Error("Home Assistant refresh service unavailable");
      }
      await this._hass.callService("homeassistant", "update_entity", { entity_id: entities });
      if (this._filterBusy) throw new Error("Дождитесь завершения записи");
      await this._loadFilters();
      if (!this._filterData) throw new Error("Не удалось получить журнал водоподготовки");
      success = true;
    } catch (_error) {
      success = false;
    }
    const elapsed = (typeof performance !== "undefined" && performance.now
      ? performance.now()
      : Date.now()) - startedAt;
    if (elapsed < 900) await this._delay(900 - elapsed);
    if (token !== this._refreshToken || !this.isConnected) return success;
    this._refreshing = false;
    this._setRefreshVisual(success ? "success" : "error");
    if (!success) this._showToast("Обновить данные не удалось");
    this._queuePatch();
    this._refreshResultTimer = window.setTimeout(() => {
      if (token !== this._refreshToken) return;
      this._refreshResultTimer = null;
      this._setRefreshVisual("idle");
    }, 1400);
    return success;
  }

  _showToast(message) {
    const toast = this.shadowRoot.querySelector(".panel-toast");
    if (!toast) return;
    if (this._toastTimer !== null) window.clearTimeout(this._toastTimer);
    toast.textContent = message;
    toast.classList.add("visible");
    this._toastTimer = window.setTimeout(() => {
      this._toastTimer = null;
      toast.classList.remove("visible");
    }, 1400);
  }
}

if (!customElements.get("nikas-water-treatment-panel")) {
  customElements.define("nikas-water-treatment-panel", NikaSWaterTreatmentPanel);
}
